from pathlib import Path
import json,gzip,base64,hashlib
D=json.loads(gzip.decompress(base64.b64decode('')))
for name,s in D.items():
 p=Path(name); old=p.read_text(encoding='utf-8'); assert hashlib.sha256(old.encode()).hexdigest()==s['base_sha'], f'base mismatch {name}'
 lines=old.splitlines(keepends=True)
 for i1,i2,new in reversed(s['ops']): lines[i1:i2]=new.splitlines(keepends=True)
 out=''.join(lines); p.write_text(out,encoding='utf-8',newline='')
 assert hashlib.sha256(out.encode()).hexdigest()==s['final_sha'], f'final mismatch {name}'
print('v1.2.3 exact patch applied')
